pub const DEFAULT_BLOCK_SIZE: u32 = 128;

/// A single query result: the similarity `score` of the document at `offset`.
///
/// Ordering is defined so that a higher `score` compares greater, with ties
/// broken by the smaller `offset` comparing greater. This lets a
/// [`std::collections::BinaryHeap`] act as a bounded top-k heap where the
/// element that should be evicted first (lowest score, then highest offset)
/// sits at the top when the ordering is reversed via [`std::cmp::Reverse`].
