/// Default maximum size in bytes for a single posting block. Used when
/// splitting a dimension's posting list into blocks and when creating the
/// blockfile writer that backs the sparse posting list.
pub const SPARSE_POSTING_BLOCK_SIZE_BYTES: usize = 8192;

/// Number of document offsets processed per scoring window during a query.
///
/// A window is scored with a flat `[u64; 64]` presence bitmap (4096 bits) and
/// a parallel `[f32; WINDOW_SIZE]` accumulator, matching the interface of
/// [`PostingCursor::drain_essential`].
const WINDOW_SIZE: usize = 4096;

#[derive(Debug, Error)]
pub enum MaxScoreError {
    #[error(transparent)]
    Blockfile(#[from] Box<dyn ChromaError>),
    #[error(transparent)]
    Posting(#[from] SparsePostingBlockError),
}

impl ChromaError for MaxScoreError {
    fn code(&self) -> ErrorCodes {
        match self {
            MaxScoreError::Blockfile(err) => err.code(),
            MaxScoreError::Posting(_) => ErrorCodes::Internal,
        }
    }
}

// ── PostingCursor ────────────────────────────────────────────────────

/// A cursor over the posting list of a single dimension.
///
/// Constructed from the dimension's [`SparsePostingBlock`]s, it decodes all
/// blocks eagerly into flat `(offset, weight)` arrays sorted by offset. The
/// cursor supports both sequential traversal (`advance`/`next`) and random
/// range access (`window_upper_bound`, `get_value`, `drain_essential`,
/// `score_candidates`).
pub struct PostingCursor {
    offsets: Vec<u32>,
    weights: Vec<f32>,
    /// Current position for sequential `advance`/`next` traversal.
    pos: usize,
}

impl PostingCursor {
    /// Build a cursor from a dimension's posting blocks (in block order).
    pub fn from_blocks(blocks: Vec<SparsePostingBlock>) -> Self {
        let total: usize = blocks.iter().map(|b| b.len()).sum();
        let mut offsets = Vec::with_capacity(total);
        let mut weights = Vec::with_capacity(total);
        for mut block in blocks {
            let (block_offsets, block_weights) = block.decode();
            offsets.extend_from_slice(block_offsets);
            weights.extend_from_slice(block_weights);
        }
        Self {
            offsets,
            weights,
            pos: 0,
        }
    }

    /// Return the first `(offset, weight)` at or after the current position
    /// where `offset >= target` and the offset passes `mask`. Advances the
    /// internal position to that entry (without consuming it). Returns `None`
    /// when the list is exhausted.
    pub fn advance(&mut self, target: u32, mask: &SignedRoaringBitmap) -> Option<(u32, f32)> {
        while self.pos < self.offsets.len() {
            let offset = self.offsets[self.pos];
            if offset >= target && mask.contains(offset) {
                return Some((offset, self.weights[self.pos]));
            }
            self.pos += 1;
        }
        None
    }

    /// Move past the current entry.
    pub fn next(&mut self) {
        if self.pos < self.offsets.len() {
            self.pos += 1;
        }
    }

    /// Maximum weight across all entries whose offset is in `[lo, hi]`
    /// (inclusive). Returns `0.0` if no entry falls in the range.
    pub fn window_upper_bound(&self, lo: u32, hi: u32) -> f32 {
        let start = self.offsets.partition_point(|&o| o < lo);
        let mut best = 0.0f32;
        let mut found = false;
        for i in start..self.offsets.len() {
            let offset = self.offsets[i];
            if offset > hi {
                break;
            }
            let weight = self.weights[i];
            if !found || weight > best {
                best = weight;
                found = true;
            }
        }
        best
    }

    /// Weight stored at exactly `offset`, or `None` if absent.
    pub fn get_value(&self, offset: u32) -> Option<f32> {
        match self.offsets.binary_search(&offset) {
            Ok(idx) => Some(self.weights[idx]),
            Err(_) => None,
        }
    }

    /// For every entry with offset in `[lo, hi]` (inclusive) that passes
    /// `mask`, add `weight * query_weight` to `accum[offset - lo]` and set bit
    /// `offset - lo` in the flat `bitmap`. Accumulates additively across calls.
    pub fn drain_essential(
        &self,
        lo: u32,
        hi: u32,
        query_weight: f32,
        accum: &mut [f32],
        bitmap: &mut [u64],
        mask: &SignedRoaringBitmap,
    ) {
        let start = self.offsets.partition_point(|&o| o < lo);
        for i in start..self.offsets.len() {
            let offset = self.offsets[i];
            if offset > hi {
                break;
            }
            if !mask.contains(offset) {
                continue;
            }
            let idx = (offset - lo) as usize;
            accum[idx] += self.weights[i] * query_weight;
            bitmap[idx / 64] |= 1u64 << (idx % 64);
        }
    }

    /// For each candidate offset in `cand_docs` that falls in `[lo, hi]` and
    /// exists in this posting list, add `weight * query_weight` to the parallel
    /// slot in `cand_scores`. Candidates absent from the list are left
    /// unchanged.
    pub fn score_candidates(
        &self,
        lo: u32,
        hi: u32,
        query_weight: f32,
        cand_docs: &[u32],
        cand_scores: &mut [f32],
    ) {
        for (i, &doc) in cand_docs.iter().enumerate() {
            if doc < lo || doc > hi {
                continue;
            }
            if let Some(weight) = self.get_value(doc) {
                cand_scores[i] += weight * query_weight;
            }
        }
    }

    fn min_offset(&self) -> Option<u32> {
        self.offsets.first().copied()
    }

    fn max_offset(&self) -> Option<u32> {
        self.offsets.last().copied()
    }
}

