            (3, vec![(0, 1.0)]),
        ];
        let reader = Box::pin(build_reader(None, vectors)).await;
        let mut incl = RoaringBitmap::new();
        incl.insert(1);
        incl.insert(3);
        let results = reader
            .query(vec![(0, 1.0)], 10, SignedRoaringBitmap::Include(incl))
            .await
            .unwrap();
        let mut offs: Vec<u32> = results.iter().map(|r| r.offset).collect();
        offs.sort();
        assert_eq!(offs, vec![1, 3]);

        let mut excl = RoaringBitmap::new();
        excl.insert(1);
        excl.insert(3);
        let results = reader
            .query(vec![(0, 1.0)], 10, SignedRoaringBitmap::Exclude(excl))
            .await
            .unwrap();
        let mut offs: Vec<u32> = results.iter().map(|r| r.offset).collect();
        offs.sort();
        assert_eq!(offs, vec![0, 2]);
    }

    #[tokio::test]
    async fn scratch_multiblock_directory() {
        // Many offsets on dim 7 -> force multiple blocks with tiny block size.
        let mut vectors = Vec::new();
        for i in 0..500u32 {
            vectors.push((i, vec![(7, 0.001 * (i as f32 + 1.0)), (8, 0.5)]));
        }
        let reader = Box::pin(build_reader(Some(256), vectors.clone())).await;
        let encoded = encode_u32(7);
        let blocks = reader.get_posting_blocks(&encoded).await.unwrap();
        assert!(blocks.len() > 1, "expected multiple blocks, got {}", blocks.len());
        for b in &blocks {
            assert!(!b.is_directory());
        }
        let dir = reader.get_directory(&encoded).await.unwrap();
        assert!(dir.is_some(), "directory should exist for multi-block dim");
        let (directory, _parts) = dir.unwrap();
        assert_eq!(directory.num_blocks(), blocks.len());
        assert_eq!(directory.max_offsets().len(), blocks.len());
        assert_eq!(directory.max_weights().len(), blocks.len());

        // Query correctness across blocks.
        let query = vec![(7, 1.0), (8, 1.0)];
        let results = reader
            .query(query.clone(), 5, SignedRoaringBitmap::full())
            .await
            .unwrap();
        let expected = exhaustive(&vectors, &query, 5);
        assert_eq!(results.len(), 5);
        for (r, e) in results.iter().zip(expected.iter()) {
            assert_eq!(r.offset, e.0);
            assert!((r.score - e.1).abs() < 5e-3);
        }
    }

